		question: "question",
		correctAnswer: "answer",
		choices: ["answer"],
		srs: {
			easeFactor,
			interval: 10,
			repetitions,
			learningStep: null,
			nextReviewDate: "2026-01-01T00:00:00.000Z",
			lastReviewDate: "2026-01-01T00:00:00.000Z",
			lapseCount,
		},
		symbolCharacter: character,
		property: "recognition",
		lessonNumber: 1,
	});
}

